    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]; comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=0 and not seen[r][c]:
                comp=set([(r,c)]); q=deque([(r,c)]); seen[r][c]=True
                while q:
                    a,b=q.popleft()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<h and 0<=nb<w and g[na][nb]==g[a][b] and not seen[na][nb]:
                                seen[na][nb]=True; comp.add((na,nb)); q.append((na,nb))
                comps.append(comp)
    bigs=[comp for comp in comps if len(comp)>=8]
    bunion=set()
    for comp in comps:
        if len(comp)>=8: bunion|=comp
    keycells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=0 and (r,c) not in bunion]
    tlps=[]
    for comp in bigs:
        mr=min(p[0] for p in comp); mc=min(p[1] for p in comp)
        tlps.append(tuple(sorted((p[0]-mr,p[1]-mc) for p in comp)))
    tpl=Counter(tlps).most_common(1)[0][0]
    H=max(p[0] for p in tpl)-min(p[0] for p in tpl)+1
    rs={r for r,_,_ in keycells}; cs={c for _,c,_ in keycells}
    if len(rs)>len(cs):
        keys=sorted(rs); seq=[next(v for r,c,v in keycells if r==rr) for rr in keys]
    else:
        keys=sorted(cs); seq=[next(v for r,c,v in keycells if c==cc) for cc in keys]
    acol=next(iter({g[p[0]][p[1]] for comp in bigs for p in comp}))
    ai=seq.index(acol)
    out=[row[:] for row in g]
    for r,c,v in keycells: out[r][c]=0
    acshapex=[comp for comp in bigs if g[list(comp)[0][0]][list(comp)[0][1]]==acol]
    a=acshapex[0]
    ao=min(p[0] for p in a); ao_c=min(p[1] for p in a)
    for i in range(len(seq)):
        color=seq[i]
        o=(ao+(i-ai)*H, ao_c)
        for dr,dc in [(p[0]-min(p[0] for p in a),p[1]-min(p[1] for p in a)) for p in a]:
            rr=o[0]+dr; ccl=o[1]+dc
            if 0<=rr<h and 0<=ccl<w: out[rr][ccl]=color
    return out
for n in ['Demo pair 1','Demo pair 2']:
    print(n, f(G[n+' input'])==G[n+' output'])
out=f(G['Test input'])
print(json.dumps(out))
